"""Pre-GPU mechanical selection, exact inputs, fixed warmups and statistical rules."""
from collections import Counter
from .common import *
def main():
 assert not (OUT/'protocol_identity.json').exists(),'Do not regenerate a frozen protocol'
 inv=load(PILOT/'artifact_hashes.json');verify(list(inv.values()))
 evidence=load(PILOT/'development_evidence_freeze.json');verify(list(evidence['all_8F2_artifacts'].values()));verify(evidence['all_prior_protected_references'])
 assert load(PILOT/'pilot_gate.json')['status']=='GATE_PARTIAL'
 tests=sorted(load(PILOT/'statistical_tests.json')['tests'],key=lambda r:(r['abs_Delta_S'],r['model'],r['co_model'],r['task_a'],r['task_b']))
 anchors=[]
 for aid,index in [('A1',len(tests)-1),('A2',(len(tests)-1)//2),('A3',0)]:
  t=tests[index];anchors.append({'anchor':aid,'type':'task_comparison','comparison':t,'ascending_rank':index+1,'state_keys':[f'{t["model"]}__{task}__{t["co_model"]}' for task in [t['task_a'],t['task_b']]]})
 noise=load(PILOT/'noise_audit.json');driver=max((r for r in noise['path_audits'] if r['included_in_gate_floor']),key=lambda r:r['bootstrap_null_abs_deltaS_p95'])
 bank=load(DEV/'physical_measurements.json')['runs'];historical=[r for r in bank if r['state_identity_sha256']==driver['state_identity_sha256'] and r['physical_raw_id'] in [v['raw_id'] for v in driver['raw_evidence']]];historical.sort(key=lambda r:r['physical_raw_id']);assert len(historical)==3
 source=historical[0];raw=load(source['raw_path']);anchors.append({'anchor':'A4','type':'historical_full_state','historical_noise_driver':driver,'historical_runs':historical,'fixed_replay_source':source,'state_keys':['historical_phi_asr_full'],'overlap_with_other_anchors':False,'interpretation':'The driving source is a full multi-model deployment, not a single co-model pair. Preserve its complete replica vector, routing, workload lambda, priming, warmup and fixed arrival/input schedule; report separately from current 9A active-pair states.'})
 save('anchor_selection.json',{'selected_at_utc':now(),'anchors':anchors,'median_rule':'Observed lower median rank floor((n-1)/2) in ascending absolute Delta-S; ties use model/co/tasks IDs. For even n this chooses one real comparison, not an interpolated fabricated state.','ranked_comparisons':tests,'selection_used_new_GPU_results':False})
 old=load(PILOT/'measurement_protocol_freeze.json');seed=min(old['repetition_seeds']);pool={r['pool_id']:r for r in [json.loads(s) for s in Path(old['input_pool']).read_text().splitlines() if s.strip()]};states={}
 for a in anchors[:3]:
  t=a['comparison']
  for task in [t['task_a'],t['task_b']]:
   for co in [None,t['co_model']]:
    key=f'{t["model"]}__{task}__{co or "none"}'
    if key in states:continue
    prior=load(PILOT/f'pair_measurements/{"pair" if co else "standalone"}/{t["model"]}__{task}__{co or "none"}__{seed}.json')
    warm=[{'worker':r['model_family'],'item':pool[r['pool_id']]} for r in prior['warmup_records']]
    states[key]={'state_key':key,'protocol_family':'current_active_pair','model':t['model'],'task':task,'co_model':co,'worker_specs':{m:old['registry'][m] for m in [t['model']]+([co] if co else [])},'target_worker':t['model'],'target_items':old['input_subsets'][str(seed)][task],'warmup_sequence':warm,'warmup_count':len(warm),'warmup_source':str(PILOT/f'pair_measurements/{"pair" if co else "standalone"}/{t["model"]}__{task}__{co or "none"}__{seed}.json'),'target_schedule_seconds':old['target_schedule_seconds'],'measurement_seconds':old['measurement_seconds'],'co_tasks':old['co_tasks'].get(co,[]),'co_items':old['input_subsets'][str(seed)],'co_backlog':old['co_backlog'],'minimum_overlap_ratio':old['minimum_overlap_ratio'],'budget_mib':49140}
 context=load(DEV/'contexts/C06.json');target='phi4mm#0'
 # Replay actual frozen per-request routing destinations; never recompute a route.
 for condition in ['none','full']:
  key='historical_phi_asr_'+condition;full=condition=='full';names=sorted(raw['transport_deployment']) if full else [target]
  def row(r,start):return {'worker':r['model'],'item':pool[r['pool_id']],'offset_seconds':max(0,(r['scheduled_time_ns']-start)/1e9),'original_request_id':r['request_id']}
  prime=[row(r,r['scheduled_time_ns']) for r in raw['priming_request_records'] if r['model'] in names]
  warm=[row(r,raw['warmup']['start_time_ns']) for r in raw['warmup_request_records'] if r['model'] in names]
  schedule=[row(r,raw['measurement_window']['start_time_ns']) for r in raw['request_records'] if full or (r['model']==target and r['task']=='asr')]
  targets=[r for r in schedule if r['worker']==target and r['item']['task_type']=='asr'];assert len(targets)==2
  states[key]={'state_key':key,'protocol_family':'historical_full_state_replay','model':'phi4mm','task':'asr','co_model':'historical_full' if full else None,'worker_specs':{n:context['registry'][n.split('#')[0]] for n in names},'target_worker':target,'target_items':[r['item'] for r in targets],'target_schedule_seconds':[r['offset_seconds'] for r in targets],'priming_sequence':prime,'warmup_sequence':warm,'warmup_count':len(warm),'warmup_seconds':10,'measurement_schedule':schedule,'measurement_seconds':210,'source_replica_vector':source['deployment'],'source_routing':source['identity']['config']['routing_rps'],'source_lambda':source['identity']['config']['workload_rps'],'source_state_hash':source['state_identity_sha256'],'budget_mib':source['budget_mib'],'M_safe_mib':source['M_safe_mib'],'co_backlog':'Frozen original open-loop per-worker request destinations; no invented saturation','minimum_overlap_ratio':None}
 from candidate_pool_audit.provenance import environment_snapshot
 live_env=environment_snapshot();expected=load(DEV/'campaign_manifest.json')['environment'];assert live_env==expected,'Environment drift; STOP'
 models=set(n.split('#')[0] for s in states.values() for n in s['worker_specs']);assets=[r for r in load(DEV/'hash_verification.json')['model_assets'] if r['model'] in models];verify([{'path':r['path'],'sha256':r['expected']} for r in assets])
 frozen_refs=list(inv.values())+list(evidence['all_8F2_artifacts'].values())+evidence['all_prior_protected_references']+[{'path':r['path'],'sha256':r['expected']} for r in assets]
 protocol={'frozen_at_utc':now(),'source_9A1_protocol_hash':sha(PILOT/'measurement_protocol_freeze.json'),'source_9A1_gate_hash':sha(PILOT/'pilot_gate.json'),'source_9A1_gate':'GATE_PARTIAL','fixed_input_seed':seed,'process_repetitions':5,'states':states,'runtime_environment':live_env,'environment_variables':{'OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1','OPENBLAS_NUM_THREADS':'1','LD_LIBRARY_PATH':load(ROOT/'results/module8c_final_real_search/startup_recovery.json')['runtime_environment_overrides']['LD_LIBRARY_PATH']},'GPU':load(DEV/'campaign_manifest.json')['GPU'],'GPU_UUID_exception':'UUID-only difference authorized by user; model, driver, physical VRAM and all other environment identities must match','input_pool_sha256':sha(old['input_pool']),'input_pool':old['input_pool'],'warmup_rule':'Replay exact warmup request identities/count/order from earliest 9A1 seed; replace time-terminated warmup with frozen count as explicitly requested for repeatability. Historical full-state warmup retains the exact 10-second source arrival schedule and count. Warmup and measurement stay separate.','measurement_rule':'Current active pair uses frozen 30 requests at i*7 seconds, 210-second window, co-backlog64 with refill. Historical A4 exactly replays its original existing workload/routing at the original budget. Neither adds a benchmark workload or memory point.','repetitions_use_different_subsets':False,'bootstrap':{'resamples':10000,'seed':92002,'CI':.95,'unit':'resample independent process repetition blocks, then matched request indices within each block; standalone/pair sample IDs resampled jointly; different target tasks have independent input resampling but shared repetition blocks'},'variance_decision':'Compare pooled within-state variance of aggregate S_run with matched-input mean(S_i), using paired stratified repetition-block bootstrap. MATCHED_INPUT iff 95% lower bound of variance(aggregate)-variance(matched mean) > 0. Otherwise AGGREGATE_PROTOCOL_RETAINED. No selection by task-effect significance.','repeatability_gate_rule':{'STRONG':'A1 has all five valid independent Delta-S_run directions matching 9A1, hierarchical 95% CI excludes zero in that direction, and bootstrap 95% lower bound of abs(mean Delta-S)-pooled within-state std is positive. Exact fixed-input/process/reset protocol checks pass. The comparison to measured std is a data-derived equality test, not an arbitrary SNR cutoff. Primary gate always uses specified aggregate S_run; matched-input sensitivity is reported separately.','PARTIAL':'A1 direction is stable at population level (mean sign matches original and more matching than opposing repetitions), but one or more STRONG conditions fail. Ties do not count as matching.','NOT_SUPPORTED':'A1 effect mean does not preserve original direction, matching independent signs do not outnumber opposing signs, or effect vanishes with CI including zero and signs lacking directional consistency. Missing/failed measurements imply INCOMPLETE rather than a fabricated negative.','noise_floor_1_1797_used_as_followup_threshold':False},'sigma_definition':'sample std(ddof=1) of five independent S_run values for each exact state; standalone/pair combination is the exact state being audited','MAD_definition':'median absolute deviation from run-level median, unscaled','between_task_variance_definition':'sample variance(ddof=1) of the two task run-level means; within-state variance is average of the two independent run variances; report ratio without magic cutoff','frozen_refs':frozen_refs,'old_results_modified':False,'complete_Module9A_started':False,'new_GPU_measurements_before_freeze':0,'retries':0}
 protocol['historical_environment_overrides']={'LD_LIBRARY_PATH':protocol['environment_variables'].pop('LD_LIBRARY_PATH')}
 protocol['diagnostics']='Same additional read-only 1 Hz GPU clocks/temperature/pstate sampling for every new run; no profiler, clock/driver/CUDA changes or inference-handler instrumentation.'
 save('protocol_identity.json',protocol)
 save('campaign_state.json',{'status':'PREPARED','completed_runs':0,'new_GPU_runs':0})
 print(json.dumps({'anchors':[(a['anchor'],a.get('comparison',{}).get('model'),a['state_keys']) for a in anchors],'unique_states':len(states),'planned_runs':len(states)*5,'environment_and_frozen_refs':'PASS'},ensure_ascii=False))
if __name__=='__main__':main()
